def transform(grid):
    h, w = len(grid), len(grid[0])

    # The background tile color is the most frequent cell value.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    base = max(counts, key=counts.get)

    # Separator lines are rows/columns whose cells are predominantly not
    # the repeated tile color. Only lines containing marker colors matter.
    rr = [r for r in range(h) if sum(v != base for v in grid[r]) > w * 0.7]
    cc = [c for c in range(w) if sum(grid[r][c] != base for r in range(h)) > h * 0.7]

    # Retain the interior marked lattice, stepping over paired duplicate
    # marker positions; the skipped duplicate positions become base color.
    if len(rr) >= 2 and len(cc) >= 2:
        r0, r1 = rr[0], rr[-1]
        c0, c1 = cc[0], cc[-1]
        rows = rr[1:-1]
        cols = cc[1:-1]
        if not rows:
            rows = rr
        if not cols:
            cols = cc
    else:
        rows, cols = rr, cc

    out = []
    for i, r in enumerate(rows):
        row = []
        for j, c in enumerate(cols):
            # Alternating locations in paired marker groups are structural
            # dividers rather than output marks.
            if j % 2 == 1 and grid[r][c] != base:
                row.append(base)
            else:
                row.append(grid[r][c])
        out.append(row)
    return out
